WITH car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_municipio,sigla_uf,area FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),pl AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM pl GROUP BY 1,2),pc AS (SELECT c.id_car_norm,c.id_municipio,c.sigla_uf,c.area,SUM(op.valor_parcela_credito/n.n_imoveis) credito_car,SUM(op.area_financiada/n.n_imoveis) area_financiada FROM `basedosdados.br_bcb_sicor.operacao` op JOIN n USING(id_referencia_bacen,numero_ordem) JOIN pl USING(id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao=2023 GROUP BY 1,2,3,4),tot AS (SELECT c.id_municipio,c.sigla_uf,SUM(op.valor_parcela_credito/n.n_imoveis) credito_total FROM `basedosdados.br_bcb_sicor.operacao` op JOIN n USING(id_referencia_bacen,numero_ordem) JOIN pl USING(id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao=2023 GROUP BY 1,2),ex AS (SELECT id_municipio,sigla_uf,SUM(credito_car) credito_excesso FROM pc WHERE area_financiada>area GROUP BY 1,2)
SELECT e.id_municipio,d.nome,e.sigla_uf,e.credito_excesso,t.credito_total,SAFE_DIVIDE(e.credito_excesso,t.credito_total) percentual_credito_excesso
FROM ex e JOIN tot t USING(id_municipio,sigla_uf) LEFT JOIN `basedosdados.br_bd_diretorios_brasil.municipio` d USING(id_municipio)
WHERE t.credito_total>=50000000 ORDER BY percentual_credito_excesso DESC LIMIT 20